query RetrieveBookings {
  retrieveBookings {
    fCNumber
    firstName
    lastName
    bookings {
      recordLocator
      bookingDate
      segments {
        cabin
        departure
        destination
        eligibility
        marketingFlight {
          airlineCode
          number
        }
        operatingFlight {
          airlineCode
          number
        }
        origin
        segmentID
      }
      passengers {
        firstName
        frequentFlyerNumber
        lastName
        passengerId
        selectedMeal
      }
    }
  }
}
